from AlgorithmImports import *
from collections import deque
import math


class PrivateLotStrategySystem(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1_000_000)

        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.spy_closes = deque(maxlen=101)
        self.aapl_red_streak = 0
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.Wilders)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data: Slice):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if data.Bars.ContainsKey(symbol):
                bars[ticker] = data.Bars[symbol]

        # Market-state quantities update whenever their respective bar exists.
        if "SPY" in bars:
            self.spy_closes.append(float(bars["SPY"].Close))

        if "AAPL" in bars:
            aapl_bar = bars["AAPL"]
            if aapl_bar.Close < aapl_bar.Open:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.aapl_rsi.Update(
                IndicatorDataPoint(aapl_bar.EndTime, float(aapl_bar.Close))
            )

        # No rule evaluation unless every subscribed ticker has today's bar.
        if len(bars) != len(self.symbols):
            return

        # Require all indicators and rolling windows used by rules to be formed.
        if len(self.spy_closes) < 101 or not self.aapl_rsi.IsReady:
            return

        spy_close = float(bars["SPY"].Close)
        aapl_close = float(bars["AAPL"].Close)

        previous_sma_100 = sum(list(self.spy_closes)[:100]) / 100.0
        current_sma_100 = sum(list(self.spy_closes)[1:]) / 100.0
        previous_spy_close = list(self.spy_closes)[-2]

        spy_crosses_above = (
            previous_spy_close <= previous_sma_100
            and spy_close > current_sma_100
        )
        spy_crosses_below = (
            previous_spy_close >= previous_sma_100
            and spy_close < current_sma_100
        )

        # Evaluate all sells before any buys.
        if self.strategy_a_lot > 0 and spy_crosses_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if self.strategy_b_lot > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        if self.strategy_a_lot == 0 and spy_crosses_above:
            quantity = math.floor(
                0.40 * self.Portfolio.TotalPortfolioValue / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if self.Portfolio.Cash >= 20_000:
                quantity = math.floor(20_000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity
